"""Source-backed report and ordinary static scientific figures, no fitted selection."""
import base64,html,json,statistics
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from .common import ARMS,SEEDS,ROOT

LABELS={'phase_joint':'Phase · joint','phase_first':'Phase · first-focused','context_joint':'Context phase · joint','context_first':'Context phase · first-focused','gru_joint':'GRU · joint','gru_first':'GRU · first-focused'}
def metric(m,n,gap,condition='normal'):
    return next(x for x in m['summary'] if (x['keys'],x['gap'],x['condition'])==(n,gap,condition))
def pct(v):return f'{100*v:.2f}%'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def render():
    summary=json.loads((ROOT/'results/SUMMARY.json').read_text());assert not summary['missing'];models=summary['models'];groups={a:[m for m in models if m['arm']==a] for a in ARMS}
    dest=ROOT.parent/'collect018_deliverables';dest.mkdir(exist_ok=True);plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
    colors=['#2b6f83','#559f9a','#a77631','#e0ae65','#6e5ba6','#ac8ec2'];fig,axs=plt.subplots(2,2,figsize=(13,8),layout='constrained');xx=np.arange(6)
    for j,(n,gap,title) in enumerate(((1,0,'One-key local positive control'),(4,0,'Four-key local primary'))):
        ax=axs[0,j]
        for i,a in enumerate(ARMS):
            vals=[100*metric(m,n,gap)['first_accuracy'] for m in groups[a]];ax.bar(i,np.mean(vals),color=colors[i],alpha=.55);ax.scatter([i]*3,vals,color=colors[i],s=36,edgecolors='black',linewidths=.5,zorder=3);ax.text(i,max(vals)+3,f'{np.mean(vals):.2f}',ha='center',fontsize=9)
        ax.axhline(90 if n==1 else 75,color='#ae6060',linestyle='--',label='Registered present-accuracy threshold')
        ax.axhline(12.5,color='#555',linestyle=':',label='Present-class constant guess (12.5%)');ax.set(title=title,ylabel='Present first-byte accuracy (%)',ylim=(0,100));ax.set_xticks(xx,[LABELS[a].replace(' · ','\n') for a in ARMS],rotation=20,ha='right');ax.legend(fontsize=8)
    ax=axs[1,0]
    for i,a in enumerate(ARMS):
        vals=[100*metric(m,4,0)['target_alphabet_mass'] for m in groups[a]];ax.scatter([i]*3,vals,c=colors[i],s=40,edgecolors='black',linewidths=.4)
    ax.set(title='Probability mass on a–h and ?',ylabel='Mean probability mass (%)',ylim=(0,100));ax.set_xticks(xx,[LABELS[a].replace(' · ','\n') for a in ARMS],rotation=20,ha='right')
    ax=axs[1,1]
    for i,a in enumerate(ARMS):
        vals=[m['ordinary_dev']['nll'] for m in groups[a]];ax.scatter([i]*3,vals,c=colors[i],s=40,edgecolors='black',linewidths=.4)
    ax.set(title='Ordinary original-text DEV (separate task)',ylabel='Byte negative log likelihood (lower is better)');ax.set_xticks(xx,[LABELS[a].replace(' · ','\n') for a in ARMS],rotation=20,ha='right')
    fig.suptitle('COLLECT018 · all three fixed-final seeds per arm',fontsize=17,fontweight='bold');fig.savefig(dest/'COLLECT018_results.png',dpi=160);fig.savefig(dest/'COLLECT018_results.pdf');plt.close(fig)
    fig,axs=plt.subplots(1,2,figsize=(12,4.2),layout='constrained')
    for i,a in enumerate(ARMS):
        vals=np.array([[w['first_accuracy']*100 for w in m['training_windows']] for m in groups[a]]);nll=np.array([[w['first_nll'] for w in m['training_windows']] for m in groups[a]])
        xs=[32,224,480,992];axs[0].plot(xs,vals.mean(0),marker='o',c=colors[i],label=LABELS[a]);axs[1].plot(xs,nll.mean(0),marker='o',c=colors[i])
    for ax in axs:
        ax.axvline(256,c='#aaa',ls=':');ax.axvline(512,c='#aaa',ls=':');ax.set_xlabel('Optimizer update (centres of fixed 64-update windows)')
    axs[0].set(title='TRAIN first-byte accuracy (includes absent queries)',ylabel='Accuracy (%)');axs[1].set(title='TRAIN first-byte cross entropy',ylabel='NLL');axs[0].legend(fontsize=8);fig.savefig(dest/'COLLECT018_training.png',dpi=160);plt.close(fig)
    embedded=lambda n:'data:image/png;base64,'+base64.b64encode((dest/n).read_bytes()).decode()
    avg=lambda a,f:statistics.mean(f(m) for m in groups[a]);aggregate=[]
    for a in ARMS:
        aggregate.append([LABELS[a],pct(avg(a,lambda m:metric(m,1,0)['first_accuracy'])),pct(avg(a,lambda m:metric(m,4,0)['first_accuracy'])),pct(avg(a,lambda m:metric(m,4,0)['absent_first'])),pct(avg(a,lambda m:metric(m,4,0)['present_question_mark_rate'])),pct(avg(a,lambda m:metric(m,4,0)['exact4'])),f"{avg(a,lambda m:m['ordinary_dev']['nll']):.4f}",f"{avg(a,lambda m:m['mean_step_seconds']):.4f}"])
    individual=[]
    for m in models:
        r=metric(m,4,0);individual.append([LABELS[m['arm']],m['seed'],pct(metric(m,1,0)['first_accuracy']),pct(r['first_accuracy']),pct(r['exact4']),pct(r['complete_maps']),pct(r['absent_first']),pct(r['target_alphabet_mass']),str(m['gates']['binding_gate']['pass_all']),m['trained_source_audit']['status']])
    binding=sum(m['gates']['binding_gate']['pass_all'] for m in models);positive=sum(m['gates']['positive_control']['pass_all'] for m in models)
    primary_means={a:avg(a,lambda m:metric(m,4,0)['first_accuracy']) for a in ARMS}
    absences={a:avg(a,lambda m:metric(m,4,0)['absent_first']) for a in ARMS}
    import collections
    audit_counts=collections.Counter(m['trained_source_audit']['status'] for m in models)
    sections=[]
    sections.append(f'<p class="eyebrow">Woyengi Intelligence Labs · internal research · 3 November 2026</p><h1>Can phase memory learn the first answer?</h1><p class="deck">COLLECT018: source-native address/value separation, a first-answer objective and a standard GRU control. All 18 fixed-final fits are retained.</p>')
    sections.append(f'<div class="callout"><b>Registered gates:</b> {positive}/18 models pass the one-key local positive control; {binding}/18 pass four-key binding. Mean four-key first-byte accuracy spans {pct(min(primary_means.values()))}–{pct(max(primary_means.values()))} across six arms. This run tests acquisition under a small training recipe; it does not identify the physical capacity of phase memory or establish a replacement for global attention.</div>')
    sections.append('<h2>What was changed</h2><p>The original phase model uses separate value and phase projections, but addresses still start from the current normalized byte representation. The context variant reuses already-computed native fast/slow banks and rotary context to form the address, admission and router input. Its value projection still sees the original normalized representation. The recurrent write, read-after path, final mixer, FFN and sparse memory remain unchanged. Context adds a projection call, with no extra parameters or state. A standalone PyTorch GRU tests whether the recipe can teach another recurrent model the same task.</p>')
    sections.append(table(['Factor','Registered treatment'],[['Model','Original phase (99,971 active/deployed parameters); context phase (99,971); GRU32/125 (100,323). All within 1%.'],['Objective','Joint = natural CE + 0.25 task CE + four-answer CE + 0.01 bank balance. First-focused adds 3 × first-answer CE. GRU has no bank-balance term.'],['Budget','Three seeds (18001–18003) per arm; 1,024 AdamW updates, batch 4 × 128 bytes, FP32, LR 0.003, clipping 1. No checkpoint selection.'],['Curriculum','One key through update256; two keys through512; four keys through1024. Source-copy answers are four bytes, variable first-answer prediction positions96–123.'],['Data','One natural TRAIN row and three constructed copy rows per update, with verbatim8-byte TRAIN quotations. TEST remains unread. DEV quotations and key first-character families are held out from TRAIN.'],['Retention','Full connected128-byte BPTT in training. Carried32-byte chunks during evaluation. Snapshots at0/256/512/1024, including model, AdamW and RNG.'],['Evaluation','All256 output bytes eligible. 24 histories per cell; 1/4keys and0/16/256byte gaps. Normal, wrong history, reset all and query swap. Exact4/maps, absent queries, restricted-choice diagnostics and ordinary8192-byte DEV kept separate.']]))
    sections.append('<h2>Results</h2><p>Rows below are three-seed means. An absent-key score counts correct “?” answers on absent queries; it is not present-versus-absent discrimination. Always answering “?” obtains100% absent accuracy and0% present accuracy. The present classes a–h are exactly balanced in DEV, so any fixed present letter scores12.5% first-byte accuracy.</p>')
    sections.append(table(['Arm','1-key first','4-key first','Absent first','Present answered ?','4-key exact4','Natural DEV NLL','CPU s/update'],aggregate))
    sections.append('<figure><img src="'+embedded('COLLECT018_results.png')+'"><figcaption>Dots show every seed; bars show means. No statistical significance or architecture ranking is inferred from three seeds and a small constructed cohort.</figcaption></figure>')
    sections.append('<figure><img src="'+embedded('COLLECT018_training.png')+'"><figcaption>Fixed64-update windows, averaged over all seeds. Vertical lines mark curriculum changes. TRAIN accuracy includes the20% absent class and must not be compared directly with present-only DEV accuracy.</figcaption></figure>')
    sections.append('<details><summary>All 18 original final models</summary>'+table(['Arm','Seed','1-key first','4-key first','Exact4','Perfect maps','Absent first','Alphabet mass','Binding gate','Source audit'],individual)+'</details>')
    sections.append('<h2>What the evidence can establish</h2><p>Output-alphabet learning, query binding, overwrite, absent-key detection and retention are distinct skills. Extra first-byte loss concentrates output probability without producing useful key-dependent retrieval here. Small normal-minus-counterfactual gaps do not establish causal retrieval. A failed GRU learnability control cannot support a phase-specific capacity verdict. The20% absent TRAIN class is individually more frequent than any one of the eight present first-letter classes (about10% each). The rejection-heavy solution is consistent with learning this marginal prior; its cause is not established by this run.</p><p>Gap256 uses resampled keys/quotation offsets and a later absolute answer position than gap0. It is a distribution-shift diagnostic, not a pure intervention on retention. One-key query swap is an identity and supplies no binding test. State resets/interventions can be out of distribution; context-phase query addressing itself depends on native state. These interventions measure pathway dependence rather than exclusive storage locations.</p>')
    localized=[]
    for m in models:
        ll=m.get('post_null_key_family_localization',{}).get('summary',[])
        ss={r['keys']:r for r in ll if r['condition']=='normal'}
        if len(ss)==2:localized.append([LABELS[m['arm']],m['seed'],pct(ss[1]['first_accuracy']),pct(ss[4]['first_accuracy']),pct(ss[4]['exact4']),pct(ss[4]['absent_first'])])
    sections.append('<details><summary>Post-partial-null key-family localization (all final models)</summary><p>This diagnostic was declared after six GRU and two native final scores were inspected. It replaces held-out n–z first-key characters with TRAIN a–m characters while preserving every quotation offset, source quote, filler byte, position and RNG draw. The easier result does not replace the registered primary or establish unseen-key generalization.</p>'+table(['Arm','Seed','Seen-family 1-key first','Seen-family 4-key first','Exact4','Absent first'],localized)+'</details>')
    ablation=[]
    for m in models:
        p=ROOT/'results/ablations'/f"{m['arm']}_{m['seed']}.json"
        if p.is_file():
            v=json.loads(p.read_text())
            for r in v.get('summary',[]):
                if (r['keys'],r['gap'])==(4,0):ablation.append([LABELS[m['arm']],m['seed'],r['condition'],pct(r['present_first']),pct(r['present_exact4']),pct(r['absent_first'])])
    sections.append('<details><summary>Declared phase/native state interventions (four-key local)</summary>'+table(['Arm','Seed','Intervention','Present first','Exact4','Absent first'],ablation)+'</details>')
    sections.append('<h2>How this relates to attention</h2><p>The model carries a bounded matrix state and queries it with learned phase features, alongside its existing recurrent banks and bounded sparse memory. It does not retain and directly compare every past token representation with every query. This avoids a dense token-pair matrix in the tested graph, while compressing history and exposing interference, routing and query-binding risks. Bounded storage is an architectural property; useful retrieval or a speed/quality advantage must be measured separately.</p><p>A linear state read is a kernel-like weighted history summary. With recurrent correction, previous writes are also transformed by later writes; it is not generally the simple sum of raw values times phase similarities. Two bidirectional sweeps or a batch all-token ridge solve would use future tokens and cannot replace causal next-token inference without changing the task.</p><p><b>Source-equation correction:</b> the deployed operator uses u = Pk / max(kᵀPk,10⁻⁸), M′ = M + g(v−Mk)uᵀ, with a separate precision update P′ = P − g(Pk)(Pk)ᵀ/(1+gkᵀPk), symmetrized. This normalized memory write is not standard RLS, whose memory gain is Pk/(1+kᵀPk). Standard RLS-to-ridge equivalence cannot be transferred to this implementation. Finite reference agreement is also not proof of IEEE behavior for arbitrary inputs.</p>')
    sections.append('<h2>Audit and limits</h2><p>'+html.escape(str(dict(audit_counts)))+'. Every original raw256-logit first argmax and all derived retrieval metrics are independently recomputed; stage diagnostics, quotation provenance and source-exposure hashes are retained. Final-weight audits reconstruct all1,024 training slabs, verify optimizer/checkpoint counters, paired initializations, replay, owner isolation, future poisoning and first-answer activation gradients. Any original numerical failures are retained at unchanged tolerances.</p><p>Three GRU-joint models initially missed a few FP32 elementwise gradient tolerances. The exhaustive continuation records every failed comparison; FP64 and global relative gradient errors are reported separately. Neither a small global error nor a later diagnostic erases an original failure. Full mathematical/source/IEEE/AD equivalence and independent qualification remain OPEN. Source tests and scoped Lean checks establish finite or local claims only.</p><p>The six smoke fits cost48 additional updates. Full fits cost18,432 updates and present9,437,184 input bytes, including repeated source bytes and generated framing. This is not a count of unique real-world text. CPU update timings come from different shared runners and are descriptive, not equal-FLOP or GPU comparisons. Natural DEV reuses exposed research data; there is no protected TEST result, promotion or deployment.</p>')
    sections.append('<h2>Research position and proposed repairs</h2><p>The current research target is reliable, query-dependent acquisition under a source-native language-model interface. Kernel optimization, larger state and a residual exact store cannot yet be credited as solutions to a failure that also occurs in local control tasks. Before a longer-context campaign, a recipe needs a successful local copying control, separate seen-family and unseen-family scores, balanced diagnostic classes and explicit false-rejection rates. All256 output bytes should remain eligible.</p>')
    sections.append(table(['Proposed experiment (not executed here)','Reason and falsification'],[['Causal key/role frontend with address-consistency supervision','Use record/query key-pair and role labels only as TRAIN auxiliary targets. Couple the write/read phase code and bank for the same key; keep inference free of oracle masks or fixed key identities. Include shuffled-pair supervision. Require local full-vocabulary copy and counterfactual dependence before raising delay.'],['Several queries from the same prefix during training','Fork an immutable history into different present and absent query keys. Directly reward different answers for different keys, at matched query/optimizer/compute budgets. A marginal rejection or fixed-letter strategy must fail the control.'],['Presence/value auxiliary losses','Report presence detection, conditional value identity and ordinary decoder accuracy separately. Reweighting or factorization alone can still learn priors; success requires original full256 greedy retrieval and low false rejection.'],['Post-write damage sentinels for a residual exact tier','After a local binder succeeds, retain a small budgeted reservoir of original key/value sentinels and measure damage from later writes. Compare promoting damaged old records against pre-write surprise and rate-matched random admission. Count sentinel and exact-store bytes together; future query usefulness remains unknown.']]))
    sections.append('<p>The native phase path still uses one phase key for both the read and write at a token. C18 separates address input from value input; it does not test a new independent read-query projection. Address/role supervision and separate query/write codes are hypotheses to register, not repairs established by these18fits.</p><p>Prior work motivates these distinctions: <a href="https://proceedings.iclr.cc/paper_files/paper/2024/hash/448fc91f669c15d10364ee01d512cc10-Abstract-Conference.html">Zoology</a> studies multi-query associative recall and the gap between easy synthetic tasks and language recall; <a href="https://proceedings.mlr.press/v235/arora24a.html">BASED</a> combines local and linear attention while studying recall/state trade-offs. <a href="https://arxiv.org/abs/2501.00663">Titans</a> uses associative-loss-driven neural memory updates and limited-window attention. These papers do not validate this phase frontend or show that pre-write surprise selects future-useful exact-store items. No novelty claim is made.</p><p>Biological pattern separation and consolidation remain design analogies. This campaign does not test Levin stress sharing, biological circuitry, residual-tiered exact-store admission, a new Triton kernel, Mamba or Qwenputer CPU integration. None is claimed as a validated repair.</p>')
    sections.append('<h2>Source record</h2><p><a href="https://github.com/FPC-effortless/TAC-OSM/pull/702">Source and results draft PR702</a> · <a href="https://github.com/FPC-effortless/TAC-OSM/actions/runs/41561294525">Original18-fit run</a> · <a href="https://github.com/FPC-effortless/pnds-lean/pull/109">Paired mathematical draft PR109</a>. Source graph7b9af0d5dccc1f52c5055db850f8f8c28c3ae70c; execution19f69b6ced3fa8baa4320f53e2b6dc2914b73308. All remain research drafts.</p><p>Relevant primary background: <a href="https://arxiv.org/abs/2412.06464">Gated Delta Networks</a>; <a href="https://docs.pytorch.org/docs/stable/generated/torch.nn.GRU.html">PyTorch GRU equations</a>; <a href="https://github.com/divagr18/qwenputer">Qwenputer source</a>; <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11356093/">Stress Sharing as Cognitive Glue</a>. No novelty claim is made for separating address/value projections or using phase features.</p>')
    style='body{font:16px/1.6 system-ui,sans-serif;color:#18313d;background:#f8faf9;max-width:1150px;margin:0 auto;padding:48px 30px}h1{font-size:44px;line-height:1.12;max-width:950px}h2{margin-top:42px;color:#184657}.eyebrow{letter-spacing:.08em;text-transform:uppercase;font-size:12px;color:#53717b}.deck{font-size:22px;color:#4b626d}.callout{padding:24px;background:#e5eff0;border-left:5px solid #2b6f83}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;background:white}th{text-align:left;background:#dfeaec}td,th{padding:12px;border-bottom:1px solid #d9e2e4;vertical-align:top}td:first-child{font-weight:600}img{width:100%;height:auto}figure{margin:32px 0}figcaption{font-size:13px;color:#526873}a{color:#1c657f}details{margin:24px 0}summary{cursor:pointer;font-weight:650}@media print{body{background:white;padding:15px}details{display:block}table{font-size:10px}}'
    page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>COLLECT018 Research Report</title><style>'+style+'</style><main>'+''.join(sections)+'</main></html>'
    (dest/'COLLECT018_RESEARCH_REPORT.html').write_text(page)
    print(json.dumps(dict(report=str(dest/'COLLECT018_RESEARCH_REPORT.html'),models=len(models),positive=positive,binding=binding,audit_statuses=dict(audit_counts))))
if __name__=='__main__':render()
